svg.script:
var _pn_temp = 60;
var _pb_heating = true;
function postValue(id, v) { console.log('FUXA post:', id, '=', v); }
function putValue(id, v) {
  v = Number(v);
  switch(id) {
    case '_pn_temp':
      _pn_temp = Math.max(20, Math.min(100, v));
      var intensity = (_pn_temp - 20) / 80;
      document.getElementById('db-heat1').setAttribute('opacity', 0.2 + intensity * 0.6);
      document.getElementById('db-heat2').setAttribute('opacity', 0.2 + intensity * 0.6);
      document.getElementById('db-heat3').setAttribute('opacity', 0.2 + intensity * 0.6);
      break;
    case '_pb_heating':
      _pb_heating = v !== 0;
      var opacity = _pb_heating ? 0.7 : 0.2;
      document.getElementById('db-heat1').setAttribute('opacity', opacity);
      document.getElementById('db-heat2').setAttribute('opacity', opacity);
      document.getElementById('db-heat3').setAttribute('opacity', opacity);
      document.getElementById('db-status').setAttribute('class', _pb_heating ? 'alarm-on' : 'alarm-off');
      break;
  }
}
var obs = new MutationObserver(function(m) {
  m.forEach(function(mu) { mu.removedNodes.forEach(function(n) { if(n.id==='fuxa-drying') obs.disconnect(); }); });
});
obs.observe(document.body, {childList:true,subtree:true});
